//! The kernel lane (T3 D1 §4.10; plan §5): each R1 case through W1a's public
//! entry, `solve_case`, with no budget limit reachable (u64::MAX for the case
//! and the invocation, recorded), then every R1 row judged (plan §6), the
//! floor check (§7), the discrimination check (§8) and the class
//! correspondence of the not-covered rows (§7.2).
use crate::cases::{Case, ControlKind, Model, Target};
use crate::compare::{judge, ControlTally, Observed, Tally, Verdict};
use crate::exact::{self, Exact};
use crate::floor;
use crate::records;
use crate::sha256::sha256_hex;
use open_pipe_stress_frame_kernel::structural::retained_api::{
    solve_case, Binary64Outcome, CaseLimit, CaseOutcome, Component, End, InvocationMeter,
    PrimitiveSource, PublishedRow, QuantityId, Refusal, RowClass, SourceParts,
};
use serde_json::Value;
use std::collections::BTreeMap;

/// One case's run.
#[derive(Clone, Debug)]
pub struct CaseRun {
    pub id: String,
    pub family: String,
    /// `selected`, `refused`, `unresolved` or `source_refused`.
    pub outcome: String,
    pub selected_precision: Option<u32>,
    pub tally: Tally,
    /// Every failure, with its reason (a failure on a covered row is a stop).
    pub failures: Vec<String>,
    /// The not-covered keys the floor check found, in row order.
    pub not_covered: Vec<String>,
    /// Not-covered rows whose published row is not `absolute_verified` or
    /// unpublishable (plan §7.2).
    pub class_mismatches: Vec<String>,
    /// Not-covered rows whose published row is `input_derived`: a displacement
    /// at a restrained DOF, published as its exact prescription (D1 §4.1.6.1
    /// rule 2a). Listed apart from the mismatches (A1 finding for ROOT).
    pub input_derived_not_covered: Vec<String>,
    pub controls: ControlTally,
    /// The deterministic per-case record (plan §12).
    pub record: Value,
    /// The published rows, for the invariance checks.
    pub published: BTreeMap<QuantityId, PublishedRow>,
}

/// The discrimination check of a case's value controls, against its reference
/// rows (plan §8). Outcome controls are decided by `run_case`.
pub fn value_controls(case: &Case) -> ControlTally {
    let rows: BTreeMap<&str, &crate::cases::Row> =
        case.rows.iter().map(|r| (r.key.as_str(), r)).collect();
    let mut t = ControlTally::default();
    for c in &case.controls {
        let ControlKind::Value(values) = &c.kind else {
            continue;
        };
        let fails = values.iter().any(|(key, v)| {
            let row = rows
                .get(key.as_str())
                .unwrap_or_else(|| panic!("{}: control {} names {key}", case.id, c.id));
            let exp = Exact::parse_decimal(&row.expected).unwrap();
            let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
            // A control's value (a magnitude too) is compared as a value.
            let obs = Exact::parse_decimal(v).unwrap();
            !exact::predicate(&obs, &exp, &scale)
        });
        let name = format!("{}:{}", case.id, c.id);
        match (c.discriminates, fails) {
            (true, true) => t.discriminated += 1,
            (true, false) => t.undiscriminated.push(name),
            (false, false) => t.non_discriminating += 1,
            (false, true) => {
                t.non_discriminating += 1;
                t.unexpectedly_failing.push(name);
            }
        }
    }
    t
}

fn value_of(rows: &BTreeMap<QuantityId, PublishedRow>, id: QuantityId) -> Result<f64, String> {
    match rows.get(&id).map(|r| r.value) {
        Some(Binary64Outcome::Normal(v)) => Ok(v),
        Some(Binary64Outcome::Subnormal { value, .. }) => Ok(value),
        Some(Binary64Outcome::Underflow { negative }) => Ok(if negative { -0.0 } else { 0.0 }),
        Some(Binary64Outcome::Overflow { .. }) => Err(format!("{id:?} overflowed")),
        None => Err(format!("{id:?} not published")),
    }
}

fn end(member: u32, j_end: bool, component: Component) -> QuantityId {
    QuantityId::EndAction {
        member,
        end: if j_end { End::J } else { End::I },
        component,
    }
}

/// The published rows a target is formed from.
fn sources(target: Target) -> Vec<QuantityId> {
    match target {
        Target::Displacement(d) => vec![QuantityId::Displacement(d)],
        Target::Reaction(d) => vec![QuantityId::Reaction(d)],
        Target::Spring { id, component } => vec![QuantityId::SpringAction {
            spring: id,
            component,
        }],
        Target::DirectionalSpring { id, component } => {
            vec![QuantityId::DirectionalSpringAction {
                spring: id,
                component,
            }]
        }
        Target::StructuralZero => vec![],
        Target::Axial(m) | Target::Extension(m) => vec![end(m, true, Component::Ux)],
        Target::Torque(m) | Target::Twist(m) => vec![end(m, true, Component::Rx)],
        Target::BendingEnd { member, j_end } => vec![
            end(member, j_end, Component::Ry),
            end(member, j_end, Component::Rz),
        ],
        Target::BendingStation(s) => vec![
            QuantityId::StationAction {
                station: s,
                component: Component::Ry,
            },
            QuantityId::StationAction {
                station: s,
                component: Component::Rz,
            },
        ],
    }
}

/// k_t and k_a of a member (DESIGN.md §4.10, with C1's pre-scaling).
pub fn member_coefficients(model: &Model, member: u32) -> (f64, f64) {
    let m = model.members.iter().find(|m| m.id == member).unwrap();
    let l = floor::member_length(
        model.nodes[m.node_i as usize],
        model.nodes[m.node_j as usize],
    );
    (
        floor::coefficient(m.shear_modulus, m.torsion_constant, l),
        floor::coefficient(m.elastic_modulus, m.area, l),
    )
}

/// What the kernel published for a target.
pub fn observe(
    target: Target,
    rows: &BTreeMap<QuantityId, PublishedRow>,
    model: &Model,
) -> Observed {
    let unavailable = |e: String| Observed::Unavailable(e);
    match target {
        Target::StructuralZero => Observed::StructuralZero,
        Target::BendingEnd { .. } | Target::BendingStation(_) => {
            let ids = sources(target);
            match (value_of(rows, ids[0]), value_of(rows, ids[1])) {
                (Ok(y), Ok(z)) => Observed::Magnitude(y, z),
                (Err(e), _) | (_, Err(e)) => unavailable(e),
            }
        }
        Target::Twist(m) | Target::Extension(m) => {
            let (kt, ka) = member_coefficients(model, m);
            match value_of(rows, sources(target)[0]) {
                Ok(v) => Observed::Value(if matches!(target, Target::Twist(_)) {
                    v / kt
                } else {
                    v / ka
                }),
                Err(e) => unavailable(e),
            }
        }
        _ => match value_of(rows, sources(target)[0]) {
            Ok(v) => Observed::Value(v),
            Err(e) => unavailable(e),
        },
    }
}

/// Runs one case with a model (the committed one, or a large model file).
pub fn run_case_with(case: &Case, model: &Model) -> CaseRun {
    run_parts(case, model, model.source_parts())
}

pub fn run_case(case: &Case) -> CaseRun {
    let model = case.model.as_ref().expect("a CI-scale case");
    run_case_with(case, model)
}

/// Runs a case on given parts (the list-permutation checks pass permuted parts).
pub fn run_parts(case: &Case, model: &Model, parts: SourceParts) -> CaseRun {
    let mut failures = Vec::new();
    let mut tally = Tally::default();
    let mut controls = value_controls(case);
    let mut published = BTreeMap::new();
    let mut not_covered = Vec::new();
    let mut class_mismatches = Vec::new();
    let mut input_derived_not_covered = Vec::new();
    let source = match PrimitiveSource::new(parts) {
        Ok(s) => s,
        Err(e) => {
            // No kernel outcome: every row fails; for a mechanism the named
            // source refusal is recorded (C10).
            for row in &case.rows {
                tally.add(&Verdict::Fail(format!("source refused: {e:?}")));
                failures.push(format!("{}: {} source refused: {e:?}", case.id, row.key));
            }
            if !case.refuse {
                failures.push(format!("{}: source refused: {e:?}", case.id));
            }
            decide_outcome_controls(case, false, &mut controls);
            let record = records::source_refused_record(case, &format!("{e:?}"), &tally);
            return CaseRun {
                id: case.id.clone(),
                family: case.family.clone(),
                outcome: "source_refused".into(),
                selected_precision: None,
                tally,
                failures,
                not_covered,
                class_mismatches,
                input_derived_not_covered,
                controls,
                record,
                published,
            };
        }
    };
    let encoding = source.encoding();
    if sha256_hex(&encoding) != case.k4src_sha256 {
        failures.push(format!(
            "{}: K4SRC sha256 differs from the generator's --model path",
            case.id
        ));
    }
    let mut meter = InvocationMeter::new(u64::MAX);
    let outcome = solve_case(source, CaseLimit::new(u64::MAX), &mut meter);
    let (label, selected_precision) = match &outcome {
        CaseOutcome::Selected(s) => ("selected", Some(s.selected_precision())),
        CaseOutcome::Refused { .. } => ("refused", None),
        CaseOutcome::Unresolved { .. } => ("unresolved", None),
    };
    if meter.exhausted() {
        failures.push(format!("{}: the invocation meter was exhausted", case.id));
    }
    let selected = matches!(outcome, CaseOutcome::Selected(_));
    decide_outcome_controls(case, selected, &mut controls);
    // ROOT's ruling on I17's A1 stop: a listed case must end unresolved with
    // no rows; leaving the list is a failure, and so is joining it.
    let listed = crate::cases::expected_unresolved().contains(&case.id);
    if listed && !matches!(outcome, CaseOutcome::Unresolved { .. }) {
        failures.push(format!(
            "{}: on the expected-unresolved list, but {}",
            case.id,
            records::outcome_text(&outcome)
        ));
    }
    if case.refuse {
        if let CaseOutcome::Selected(s) = &outcome {
            failures.push(format!(
                "{}: a mechanism was published ({} rows)",
                case.id,
                s.publish().rows.len()
            ));
        }
    } else if let CaseOutcome::Selected(s) = &outcome {
        for r in &s.publish().rows {
            published.insert(r.id, r.clone());
        }
        let bodies = model.bodies();
        if bodies.iter().any(|&b| b != 0) {
            failures.push(format!("{}: more than one body", case.id));
        }
        let scales = floor::scales(case, model);
        for row in &case.rows {
            let exp = Exact::parse_decimal(&row.expected).unwrap();
            let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
            let covered = exact::covered(&exp, &scale, floor::row_scale(row, &scales));
            let verdict = match model.resolve(&row.key) {
                Ok(target) => {
                    let v = judge(&observe(target, &published, model), &exp, &scale, covered);
                    if !covered {
                        not_covered.push(row.key.clone());
                        for id in sources(target) {
                            let restrained = matches!(id, QuantityId::Displacement(d)
                                if model.constraints.contains(&(d.node, d.component.index())));
                            match published.get(&id).map(|r| &r.class) {
                                Some(RowClass::AbsoluteVerified { .. })
                                | Some(RowClass::Unpublishable) => {}
                                Some(RowClass::InputDerived) if restrained => {
                                    input_derived_not_covered
                                        .push(format!("{}:{}", case.id, row.key))
                                }
                                other => class_mismatches.push(format!(
                                    "{}: {} ({id:?} is {other:?})",
                                    case.id, row.key
                                )),
                            }
                        }
                    }
                    v
                }
                Err(e) => Verdict::Fail(e),
            };
            if let Verdict::Fail(why) = &verdict {
                failures.push(format!("{}: {} ({}) {why}", case.id, row.key, row.expected));
            }
            tally.add(&verdict);
        }
    } else if listed && matches!(outcome, CaseOutcome::Unresolved { .. }) {
        for _row in &case.rows {
            tally.add(&Verdict::ExpectedUnresolved);
        }
    } else {
        for _row in &case.rows {
            tally.add(&Verdict::Fail(format!("case {label}")));
        }
        failures.push(format!(
            "{}: not selected: {}",
            case.id,
            records::outcome_text(&outcome)
        ));
    }
    let record = records::case_record(case, &outcome, &tally, &meter);
    CaseRun {
        id: case.id.clone(),
        family: case.family.clone(),
        outcome: label.into(),
        selected_precision,
        tally,
        failures,
        not_covered,
        class_mismatches,
        input_derived_not_covered,
        controls,
        record,
        published,
    }
}

/// Outcome controls (plan §8): on a mechanism, each describes publishing a
/// solution, so the refusal discriminates it; on a stable model (the RF-MECH
/// companion), NC-FALSE-MECHANISM is a refusal, so the selection does.
fn decide_outcome_controls(case: &Case, selected: bool, t: &mut ControlTally) {
    for c in &case.controls {
        if let ControlKind::Outcome(_) = c.kind {
            let discriminated = if case.refuse { !selected } else { selected };
            match (c.discriminates, discriminated) {
                (true, true) => t.discriminated += 1,
                (true, false) => t.undiscriminated.push(format!("{}:{}", case.id, c.id)),
                (false, _) => t.non_discriminating += 1,
            }
        }
    }
}

/// A refusal's description without platform-dependent binary64 values (the
/// witness's rigid parameters come from FK's geometry, which uses `hypot`).
pub fn refusal_text(r: &Refusal) -> String {
    match r {
        Refusal::MechanismWitnessed { body, .. } => {
            format!("MechanismWitnessed {{ body: {body} }}")
        }
        other => format!("{other:?}"),
    }
}

//! The comparison and report engine (T3 D1 §4.10's table; plan §6.3).
//!
//! Each R1 row gets exactly one verdict: `pass`, `fail`, `not_covered` (with
//! whether the predicate held, never a pass), `pass_absolute_range` (the
//! expected value has no binary64 value; separately counted), or
//! `structural_zero` (no published row by construction; R1's value must be
//! exactly 0), or `expected_unresolved` (the row of a case on the committed
//! expected-unresolved list, which ended honestly unresolved with no rows:
//! ROOT's ruling on THIN-A and THIN-B; never a pass). The report shows
//! passes, absolute-range passes and not-covered comparisons as three
//! separate numbers, and the six tallies must add up to the rows compared.
use crate::exact::{self, Exact};
use std::fmt;

/// What the kernel published for a row.
#[derive(Clone, Debug, PartialEq)]
pub enum Observed {
    /// A binary64 value (an `Underflow` row is observed as its rounding, ±0).
    Value(f64),
    /// The two components of a bending magnitude.
    Magnitude(f64, f64),
    /// No row by construction (plan §4.2).
    StructuralZero,
    /// Nothing comparable was published (missing, or overflowed).
    Unavailable(String),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Verdict {
    Pass,
    Fail(String),
    NotCovered { predicate_held: bool },
    PassAbsoluteRange,
    StructuralZero,
    ExpectedUnresolved,
}

fn holds(obs: &Observed, exp: &Exact, scale: &Exact) -> Option<bool> {
    match obs {
        Observed::Value(v) => Some(exact::predicate(&Exact::from_f64(*v), exp, scale)),
        Observed::Magnitude(y, z) => Some(exact::magnitude_predicate(*y, *z, exp, scale)),
        _ => None,
    }
}

/// The verdict of one row: `covered` is the floor check's decision.
pub fn judge(obs: &Observed, exp: &Exact, scale: &Exact, covered: bool) -> Verdict {
    if *obs == Observed::StructuralZero {
        return if exp.is_zero() {
            Verdict::StructuralZero
        } else {
            Verdict::Fail("structural zero with a nonzero reference".into())
        };
    }
    if !covered {
        return Verdict::NotCovered {
            predicate_held: holds(obs, exp, scale).unwrap_or(false),
        };
    }
    match holds(obs, exp, scale) {
        None => Verdict::Fail(match obs {
            Observed::Unavailable(why) => why.clone(),
            _ => unreachable!(),
        }),
        Some(true) if exact::outside_binary64(exp) => Verdict::PassAbsoluteRange,
        Some(true) => Verdict::Pass,
        Some(false) => Verdict::Fail("predicate".into()),
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Tally {
    pub rows: usize,
    pub pass: usize,
    pub pass_absolute_range: usize,
    pub not_covered: usize,
    pub structural_zero: usize,
    pub expected_unresolved: usize,
    pub fail: usize,
}

impl Tally {
    pub fn add(&mut self, v: &Verdict) {
        self.rows += 1;
        match v {
            Verdict::Pass => self.pass += 1,
            Verdict::PassAbsoluteRange => self.pass_absolute_range += 1,
            Verdict::NotCovered { .. } => self.not_covered += 1,
            Verdict::StructuralZero => self.structural_zero += 1,
            Verdict::ExpectedUnresolved => self.expected_unresolved += 1,
            Verdict::Fail(_) => self.fail += 1,
        }
    }

    pub fn merge(&mut self, o: &Tally) {
        self.rows += o.rows;
        self.pass += o.pass;
        self.pass_absolute_range += o.pass_absolute_range;
        self.not_covered += o.not_covered;
        self.structural_zero += o.structural_zero;
        self.expected_unresolved += o.expected_unresolved;
        self.fail += o.fail;
    }

    /// Every row has exactly one verdict.
    pub fn accounted(&self) -> bool {
        self.pass
            + self.pass_absolute_range
            + self.not_covered
            + self.structural_zero
            + self.expected_unresolved
            + self.fail
            == self.rows
    }
}

impl fmt::Display for Tally {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "rows {}: passes {}, absolute-range passes {}, not covered {} | structural zeros {}, \
             expected unresolved {}, failures {}",
            self.rows,
            self.pass,
            self.pass_absolute_range,
            self.not_covered,
            self.structural_zero,
            self.expected_unresolved,
            self.fail
        )
    }
}

/// The discrimination tally of a set of cases (plan §8).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ControlTally {
    /// Discriminating controls that fail the predicate (or, for outcome
    /// controls, whose defect the kernel's outcome excludes).
    pub discriminated: usize,
    /// R1's non-discriminating controls (reported, never dropped).
    pub non_discriminating: usize,
    /// Discriminating controls that pass: each blocks the gate.
    pub undiscriminated: Vec<String>,
    /// Non-discriminating controls that V-K finds failing anyway (a
    /// difference from R1's own analysis; listed).
    pub unexpectedly_failing: Vec<String>,
}

impl ControlTally {
    pub fn merge(&mut self, o: &ControlTally) {
        self.discriminated += o.discriminated;
        self.non_discriminating += o.non_discriminating;
        self.undiscriminated
            .extend(o.undiscriminated.iter().cloned());
        self.unexpectedly_failing
            .extend(o.unexpectedly_failing.iter().cloned());
    }
}

//! The zero-scale floor check (T3 D1 §4.10, V1-S8, F2; plan §7).
//!
//! S\* per kind is formed from the case's reference values by D1 §4.1.6.1
//! items 4–6, in binary64 and in the stated order: S(kind) is the largest
//! |fl(exp)| of the kind (R1's class without `@region`), L_b is the body's
//! extent from the adapted node coordinates, and the four kinds are coupled.
//! Twist and extension are variant F: S\*_tw(m) = fl(mo/k_t) and
//! S\*_ext(m) = fl(fo/k_a), with k_t and k_a as §4.10 forms them (C1 below).
//! A comparison is covered iff max(|exp|, scale) ≥ R·S\*, R = 2^-34, decided
//! exactly (`exact::covered`).
use crate::cases::{Case, Model, Row};
use std::collections::BTreeMap;

/// R = 2^-34 (D1 §4.1.6, bits `0x3DD0000000000000`).
pub const R_BITS: u64 = 0x3DD0_0000_0000_0000;

pub fn r() -> f64 {
    f64::from_bits(R_BITS)
}

fn is_normal(x: f64) -> bool {
    x.is_normal()
}

/// FK's element length: `norm(subtract(xj, xi))` = `dot(v, v).sqrt()`, the
/// products and sums left to right (`FK/lib.rs` `norm`, `dot`).
pub fn member_length(xi: [f64; 3], xj: [f64; 3]) -> f64 {
    let v = [xj[0] - xi[0], xj[1] - xi[1], xj[2] - xi[2]];
    (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt()
}

/// §4.10's k = fl(fl(a·b)/L), where both intermediates are normal binary64
/// numbers; None where the design's formula is not defined.
pub fn design_coefficient(a: f64, b: f64, length: f64) -> Option<f64> {
    let p = a * b;
    let q = p / length;
    (is_normal(p) && is_normal(q)).then_some(q)
}

/// 2^k for |k| ≤ 1022 (a normal power of two), from its bits.
fn pow2(k: i32) -> f64 {
    assert!((-1022..=1023).contains(&k));
    f64::from_bits(((1023 + k) as u64) << 52)
}

/// x·2^k exactly for a normal result, in steps that keep every factor normal.
fn scale2(mut x: f64, mut k: i32) -> f64 {
    while k != 0 {
        let s = k.clamp(-1000, 1000);
        x *= pow2(s);
        k -= s;
    }
    x
}

/// The binary exponent e with |x| in [2^e, 2^(e+1)) for a finite nonzero x.
fn exponent(x: f64) -> i32 {
    let bits = x.to_bits();
    let biased = ((bits >> 52) & 0x7ff) as i32;
    if biased == 0 {
        let fraction = bits & ((1u64 << 52) - 1);
        -1075 + (64 - fraction.leading_zeros() as i32)
    } else {
        biased - 1023
    }
}

/// k = fl(fl(a·b)/L), ROOT's C1 ruling: where the design's formula is defined
/// it is used as written; elsewhere (RF-RANGE LEF-small, where fl(G·J) rounds
/// to 0, and LEF-large, where it overflows) the same two operations run on b
/// pre-scaled by an exact power of two s, chosen so that a·b·2^s lies in
/// [1, 4), and the quotient is unscaled exactly. For normal results a
/// rounding commutes with an exact power-of-two scaling, so the two agree
/// bit for bit wherever the design's intermediates are normal (tested on
/// every member of every case).
pub fn coefficient(a: f64, b: f64, length: f64) -> f64 {
    if let Some(k) = design_coefficient(a, b, length) {
        return k;
    }
    prescaled_coefficient(a, b, length)
}

/// The pre-scaled form alone (exposed for C1's equality test).
pub fn prescaled_coefficient(a: f64, b: f64, length: f64) -> f64 {
    let s = -(exponent(a) + exponent(b));
    let q = (a * scale2(b, s)) / length;
    scale2(q, -s)
}

/// S\* of one case: the four coupled kinds and, per member (by R1 name), the
/// variant-F twist and extension scales.
#[derive(Clone, Debug, PartialEq)]
pub struct Scales {
    /// translation, rotation, force, moment.
    pub kinds: [f64; 4],
    pub members: BTreeMap<String, (f64, f64)>,
}

fn kind_index(kind: &str) -> Option<usize> {
    ["translation", "rotation", "force", "moment"]
        .iter()
        .position(|k| *k == kind)
}

/// D1 §4.1.6.1 item 5: L_b from the body's node coordinates.
pub fn body_extent(nodes: &[[f64; 3]]) -> f64 {
    let mut d = [0.0f64; 3];
    for (a, slot) in d.iter_mut().enumerate() {
        let hi = nodes.iter().map(|p| p[a]).fold(f64::NEG_INFINITY, f64::max);
        let lo = nodes.iter().map(|p| p[a]).fold(f64::INFINITY, f64::min);
        *slot = hi - lo;
    }
    (d[0] * d[0] + d[1] * d[1] + d[2] * d[2]).sqrt()
}

/// D1 §4.1.6.1 item 6, in its order.
pub fn couple(s: [f64; 4], extent: f64) -> [f64; 4] {
    let [s_tr, s_ro, s_fo, s_mo] = s;
    if extent == 0.0 {
        return s;
    }
    [
        s_tr.max(extent * s_ro),
        s_ro.max(s_tr / extent),
        s_fo.max(s_mo / extent),
        s_mo.max(extent * s_fo),
    ]
}

/// S(kind) = the largest |fl(exp)| of each kind over `values`.
pub fn maxima<'a>(values: impl Iterator<Item = (&'a str, &'a str)>) -> [f64; 4] {
    let mut s = [0.0f64; 4];
    for (kind, expected) in values {
        if let Some(k) = kind_index(kind) {
            let v: f64 = expected.parse().expect("decimal");
            s[k] = s[k].max(v.abs());
        }
    }
    s
}

/// S\* from given maxima and the model (one body: asserted by the caller).
pub fn scales_from(maxima: [f64; 4], model: &Model) -> Scales {
    let kinds = couple(maxima, body_extent(&model.nodes));
    let (fo, mo) = (kinds[2], kinds[3]);
    let members = model
        .members
        .iter()
        .map(|m| {
            let l = member_length(
                model.nodes[m.node_i as usize],
                model.nodes[m.node_j as usize],
            );
            let kt = coefficient(m.shear_modulus, m.torsion_constant, l);
            let ka = coefficient(m.elastic_modulus, m.area, l);
            (m.name.clone(), (mo / kt, fo / ka))
        })
        .collect();
    Scales { kinds, members }
}

/// S\* of a case from its reference rows.
pub fn scales(case: &Case, model: &Model) -> Scales {
    scales_from(
        maxima(case.rows.iter().map(|r| (r.kind(), r.expected.as_str()))),
        model,
    )
}

/// The S\* a row is floored against.
pub fn row_scale(row: &Row, scales: &Scales) -> f64 {
    match kind_index(row.kind()) {
        Some(k) => scales.kinds[k],
        None => {
            let member = row.key.split_once('.').expect("tw.<m>/ext.<m>").1;
            let (tw, ext) = scales.members[member];
            match row.kind() {
                "twist" => tw,
                "extension" => ext,
                other => panic!("unknown class {other}"),
            }
        }
    }
}

/// The keys of a case's rows below the floor, in row order.
pub fn not_covered(case: &Case, model: &Model, scales: &Scales) -> Vec<String> {
    let _ = model;
