            let exp = crate::exact::Exact::parse_decimal(&row.expected).unwrap();
            let scale = crate::exact::Exact::parse_decimal(case.scale_of(row)).unwrap();
            !crate::exact::covered(&exp, &scale, row_scale(row, scales))
        })
        .map(|row| row.key.clone())
        .collect()
}

